def _expect_items(
    parent: ET.Element,
    rules: tuple[_ItemRule, ...],
    context: str,
    *,
    has_chunks: bool = False,
) -> list[ET.Element]:
    items = _item_elements(parent, context, has_chunks=has_chunks)
    _reject_unexpected_item_names(items, {rule.name for rule in rules}, context)
    _validate_item_rules(items, rules, context)
    return items


def _item_elements(
    parent: ET.Element,
    context: str,
    *,
    has_chunks: bool = False,
) -> list[ET.Element]:
    _reject_structural_text(parent, context)
    expected_tags = ["items", "chunks"] if has_chunks else ["items"]
    actual_tags = [child.tag for child in parent]
    if actual_tags != expected_tags:
        raise ArchiveSchemaError(
            f"{context} child elements are outside the canonical generated schema"
        )
    wrapper = parent[0]
    _expect_count_wrapper(wrapper, "items", context)
    _reject_structural_text(wrapper, f"{context} items")
    elements = list(wrapper)
    if any(element.tag != "item" for element in elements):
        raise ArchiveSchemaError(
            f"{context} contains an unexpected tag outside the generated schema"
        )
    return elements


def _chunk_elements(parent: ET.Element, context: str) -> list[ET.Element]:
    chunks = parent.find("./chunks")
    if chunks is None:
        raise ArchiveSchemaError(f"{context} is missing canonical chunks")
    _expect_count_wrapper(chunks, "chunks", context)
    _reject_structural_text(chunks, f"{context} chunks")
    elements = list(chunks)
    if any(element.tag != "chunk" for element in elements):
        raise ArchiveSchemaError(
            f"{context} contains an unexpected tag outside the generated schema"
        )
    return elements


def _expect_chunks(
    parent: ET.Element,
    expected: tuple[tuple[str, int | None], ...],
    context: str,
) -> list[ET.Element]:
    elements = _chunk_elements(parent, context)
    expected_names = [name for name, _index in expected]
    actual_names = [element.get("name") for element in elements]
    for name in set(expected_names):
        expected_count = expected_names.count(name)
        actual_count = actual_names.count(name)
        if expected_count == 1 and actual_count != 1:
            if actual_count == 0:
                raise ArchiveSchemaError(f"{context} is missing {name}")
            raise ArchiveSchemaError(
                f"{context} {name} must appear exactly one time; found {actual_count}"
            )
    unexpected = next((name for name in actual_names if name not in expected_names), None)
    if unexpected is not None:
        raise ArchiveSchemaError(
            f"{context} has unexpected chunk {unexpected!r} outside the generated schema"
        )
    if actual_names != expected_names:
        raise ArchiveSchemaError(f"{context} chunks are not in canonical generated order")
    for element, (name, index) in zip(elements, expected, strict=True):
        attributes = {"name": name}
        if index is not None:
            attributes["index"] = str(index)
        _expect_attributes(element, attributes, f"{context} {name}")
    return elements


def _validate_item_rules(
    elements: list[ET.Element],
    rules: tuple[_ItemRule, ...],
    context: str,
) -> None:
    expected_names = [rule.name for rule in rules]
    actual_names = [element.get("name") for element in elements]
    for name in set(expected_names):
        expected_count = expected_names.count(name)
        actual_count = actual_names.count(name)
        if expected_count == 1 and actual_count != 1:
            if actual_count == 0:
                raise ArchiveSchemaError(f"{context} is missing {name}")
            raise ArchiveSchemaError(
                f"{context} {name} must appear exactly one time; found {actual_count}"
            )
    if actual_names != expected_names:
        raise ArchiveSchemaError(f"{context} items are not in canonical generated order")
    for element, rule in zip(elements, rules, strict=True):
        attributes = {
            "name": rule.name,
            "type_name": rule.type_name,
            "type_code": rule.type_code,
        }
        if rule.index is not None:
            attributes["index"] = str(rule.index)
        _expect_attributes(element, attributes, f"{context} {rule.name}")
        _validate_item_content(element, rule, context)


def _validate_item_content(element: ET.Element, rule: _ItemRule, context: str) -> None:
    children = list(element)
    expected_child_names = [name for name, _value in rule.children]
    if children and element.text and element.text.strip():
        raise ArchiveSchemaError(
            f"{context} {rule.name} contains unexpected structural text"
        )
    if [child.tag for child in children] != expected_child_names:
        raise ArchiveSchemaError(
            f"{context} {rule.name} child elements are outside the canonical generated schema"
        )
    for child, (name, expected_value) in zip(children, rule.children, strict=True):
        _expect_attributes(child, {}, f"{context} {rule.name} {name}")
        if list(child):
            raise ArchiveSchemaError(
                f"{context} {rule.name} {name} contains an unexpected generated-schema child"
            )
        if child.tail and child.tail.strip():
            raise ArchiveSchemaError(
                f"{context} {rule.name} contains unexpected structural text"
            )
        if expected_value is not _ANY and (child.text or "") != expected_value:
            raise ArchiveSchemaError(f"{context} {rule.name} {name} is not canonical")
        if expected_value is _ANY:
            _validate_canonical_number(child.text or "", f"{context} {rule.name} {name}")
    if rule.type_name == "gh_guid":
        try:
            identifier = UUID(element.text or "")
        except ValueError as error:
            raise ArchiveSchemaError(
                f"{context} {rule.name} must be a valid UUID"
            ) from error
        if str(identifier) != (element.text or ""):
            raise ArchiveSchemaError(
                f"{context} {rule.name} must use canonical UUID text"
            )
    if rule.type_name == "gh_string" and rule.name != "Text":
        value = element.text or ""
        if contains_unsafe_terminal_text(value):
            if any(
                ord(character) < 0x20 or 0x7F <= ord(character) < 0xA0
                for character in value
            ):
                raise ArchiveSchemaError(
                    f"{context} {rule.name} contains a terminal control character"
                )
            raise ArchiveSchemaError(
                f"{context} {rule.name} contains an unsafe terminal formatting character"
            )
        if not rule.allow_empty and not value:
            raise ArchiveSchemaError(f"{context} {rule.name} must be non-empty")
        if rule.max_length is not None and len(value) > rule.max_length:
            raise ArchiveSchemaError(
                f"{context} {rule.name} must contain at most {rule.max_length} characters"
            )
        if rule.trimmed and value != value.strip():
            raise ArchiveSchemaError(
                f"{context} {rule.name} must not start or end with whitespace"
            )
    if rule.value is not _ANY and (element.text or "") != rule.value:
        raise ArchiveSchemaError(f"{context} {rule.name} is not canonical")


def _reject_unexpected_item_names(
    elements: list[ET.Element],
    allowed: set[str],
    context: str,
) -> None:
    unexpected = next(
        (element.get("name") for element in elements if element.get("name") not in allowed),
        None,
    )
    if unexpected is not None:
        raise ArchiveSchemaError(
            f"{context} has unexpected item {unexpected!r} outside the generated schema"
        )


def _expect_count_wrapper(element: ET.Element, tag: str, context: str) -> None:
    if element.tag != tag or set(element.attrib) != {"count"}:
        raise ArchiveSchemaError(f"{context} {tag} attributes are not canonical")


def _expect_attributes(element: ET.Element, expected: dict[str, str], context: str) -> None:
    if element.attrib != expected:
        if "index" in expected and element.get("index") != expected["index"]:
            raise ArchiveSchemaError(f"{context} index is not canonical")
        raise ArchiveSchemaError(f"{context} attributes are not canonical")


def _reject_structural_text(element: ET.Element, context: str) -> None:
    if element.text and element.text.strip():
        raise ArchiveSchemaError(f"{context} contains unexpected structural text")
    for child in element:
        if child.tail and child.tail.strip():
            raise ArchiveSchemaError(f"{context} contains unexpected structural text")


def _validate_canonical_number(value: str, context: str) -> None:
    try:
        number = float(value)
    except ValueError as error:
        raise ArchiveSchemaError(f"{context} must be a canonical numeric coordinate") from error
    if not math.isfinite(number) or format(number, ".15g") != value:
        raise ArchiveSchemaError(f"{context} must be a canonical numeric coordinate")
